const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const brooklyn = ee.Geometry.Point([-73.95, 40.65]).buffer(5000); // 5km buffer around Brooklyn center

  const periods = {
    '2018': ['2018-10-01', '2018-10-24'],
    '2019': ['2019-10-01', '2019-10-24'],
    '2021': ['2021-10-01', '2021-10-24']
  };

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const results = {};

  for (const [year, dates] of Object.entries(periods)) {
    const filtered = collection
      .filterDate(dates[0], dates[1])
      .filterBounds(brooklyn);

    const count = filtered.size().getInfo();
    console.log(`${year} Images: ${count}`);

    if (count === 0) {
      console.log(`No data for ${year}.`);
      console.log("<answer>C1</answer>");
      return;
    }

    // 3. Processing with QA filtering
    const masked = filtered.map(function(img) {
      const qa = img.select('qa_value');
      const mask = qa.gte(0.75);
      return img.updateMask(mask);
    });

    const composite = masked.mean();

    // Check valid pixels
    const pixelCount = composite.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: brooklyn,
      scale: 1000,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    if (pixelCount === 0) {
      console.log(`No valid pixels for ${year} after QA filtering.`);
      console.log("<answer>C2</answer>");
      return;
    }

    // 4. Calculation
    const meanNO2 = composite.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: brooklyn,
      scale: 1000,
      maxPixels: 1e9
    }).get('tropospheric_NO2_column_number_density').getInfo();

    results[year] = {
      value: meanNO2,
      pixels: pixelCount
    };

    console.log(`${year}: NO2=${meanNO2 ? meanNO2.toExponential(3) : 'null'} mol/m², Pixels=${pixelCount}`);
  }

  // 5. Validation & Final Answer
  if (results['2018'].value === null || results['2019'].value === null || results['2021'].value === null) {
    console.log("Calculation failed for one or more years.");
    console.log("<answer>C3</answer>");
    return;
  }

  const lower2018 = results['2021'].value < results['2018'].value;
  const lower2019 = results['2021'].value < results['2019'].value;

  console.log(`\n2021 < 2018: ${lower2018}, 2021 < 2019: ${lower2019}`);

  if (lower2018 && lower2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
